      provide: getRepositoryToken(User),
      useValue: { findOne: jest.fn(), create: jest.fn((d) => d), save: jest.fn() },
    },
  ],
}).compile();

service = module.get(UsersService);
const repo = module.get(getRepositoryToken(User));

Почему: убери оба импорта TypeOrmModule — именно они открывают реальный пул. Объяви UsersService реальным провайдером и подставь repository useValue-дублёром по ключу getRepositoryToken(User), точному токену, в который резолвится @InjectRepository(User). Каждый метод — это jest.fn(), который можно программировать (repo.findOne.mockResolvedValue(...)) и проверять. Соединение не открывается, поэтому тест быстрый и не флакает на таймауте пула. (Если обязательно нужен imports: [UsersModule], используй вместо этого .overrideProvider(getRepositoryToken(User)).useValue(mock).)
